package equivalent;

import metadata.BehavioralDifference;
import metadata.DifferenceType;

import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;

class ClonePair13013DifferenceFindingTest {

    private final ClonePair13013 subject = new ClonePair13013();

    /**
     * Generated by Claude Code (Claude Fable 5.1).
     * Difference type: return_value.
     * Difference manifestation: the methods return different values.
     */
    @Test
    @BehavioralDifference(DifferenceType.RETURN_VALUE)
    void methodsLowerCaseNonAsciiLettersDifferently() {
        // method1 applies String.toLowerCase(), which maps the Kelvin sign U+212A to 'k',
        // whereas method2 only folds the ASCII letters 'A' to 'Z' and treats U+212A as a separator.
        String kelvinSign = "\u212A";

        assertEquals(11L, subject.method1(kelvinSign));
        assertEquals(0L, subject.method2(kelvinSign));
    }
}
